import 'package:dio/dio.dart';
import '../../../core/networking/player_api_client.dart';
class KycStatusPayload { final String status; final String? verifiedAt; const KycStatusPayload({required this.status,this.verifiedAt}); factory KycStatusPayload.fromJson(Map<String,dynamic> j)=>KycStatusPayload(status:j['status'] as String? ?? 'not_started',verifiedAt:j['verifiedAt'] as String? ?? j['verified_at'] as String?); }
class KycApi { final PlayerApiClient client; const KycApi(this.client); Future<KycStatusPayload> status() async { final r=await client.get('/kyc'); final b=Map<String,dynamic>.from(r.data as Map); if(b['ok']!=true) throw DioException(requestOptions:r.requestOptions,response:r,message:'KYC status failed'); return KycStatusPayload.fromJson(Map<String,dynamic>.from(b['data'] as Map)); } Future<Map<String,dynamic>> submit({String? fullName, String? cnicNumber, String? documentType}) async { final Map<String, dynamic> body = {}; if(fullName != null && fullName.isNotEmpty) body['fullName'] = fullName; if(cnicNumber != null && cnicNumber.isNotEmpty) body['cnicNumber'] = cnicNumber; if(documentType != null && documentType.isNotEmpty) body['documentType'] = documentType; final r=await client.post('/kyc/submit',data: body); final b=Map<String,dynamic>.from(r.data as Map); if(b['ok']!=true) throw DioException(requestOptions:r.requestOptions,response:r,message:'KYC submission failed'); return Map<String,dynamic>.from(b['data'] as Map); } }
